impl<S: gx::Slots, T: gx::Coef, O: gx::Orientation, OV: gx::Orientation> gx::Transform<Pseudoscalar<S, T, O>> for gx::Unit<Point<(), T, OV>> {
    type Output = Pseudoscalar<S, T, O>;
    #[inline(always)]
    fn transform(self, x: Pseudoscalar<S, T, O>) -> Pseudoscalar<S, T, O> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[2].mul_add(v[2], -T::from_i64(1));
            T::check_unit(&[u1]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 1>(&x.c) {
        let t0 = v[2] * v[2];
        let t1 = xv[0] * t0;
            return Pseudoscalar { o: core::marker::PhantomData, c: gx::slots::from_values::<S, T, 1>([t1]) };
        }
        let m0 = v[2] * v[2];
        let x = x.c.map(gx::SlotArr::<S, T>);
        Pseudoscalar { o: core::marker::PhantomData, c: [(x[0].scale(m0)).0] }
    }
}

